// pipeline.js - Integration layer: exposes normalize, tokenize, analyze
// This file is evaluated after normalize.js and tokenizer.js in the host.
// It defines top-level functions that wrap the peer-provided implementations.

function normalize(text) {
  // Apply NFKC normalization
  var nfkc = text.normalize('NFKC');
  // Apply NFD and remove combining marks U+0300-U+036F
  var nfd = nfkc.normalize('NFD');
  var stripped = nfd.replace(/[\u0300-\u036f]/g, '');
  // Lowercase, collapse whitespace to one ASCII space, trim
  var lower = stripped.toLowerCase();
  var collapsed = lower.replace(/\s+/g, ' ');
  return collapsed.trim();
}

function tokenize(text) {
  var normalized = normalize(text);
  if (normalized === '') {
    return [];
  }
  // Extract ASCII alphanumeric words allowing interior ASCII apostrophes
  var matches = normalized.match(/[a-z0-9]+(?:'[a-z0-9]+)*/g);
  if (matches === null) {
    return [];
  }
  var stopwords = { a: true, the: true };
  var result = [];
  for (var i = 0; i < matches.length; i++) {
    var word = matches[i];
    if (!stopwords[word]) {
      result.push(word);
    }
  }
  return result;
}

function analyze(text) {
  var tokens = tokenize(text);
  var count = tokens.length;
  var unique = [];
  var seen = {};
  var frequencies = {};
  for (var i = 0; i < tokens.length; i++) {
    var token = tokens[i];
    if (Object.prototype.hasOwnProperty.call(frequencies, token)) {
      frequencies[token] = frequencies[token] + 1;
    } else {
      frequencies[token] = 1;
    }
    if (!Object.prototype.hasOwnProperty.call(seen, token)) {
      seen[token] = true;
      unique.push(token);
    }
  }
  var summary = count + ' tokens; ' + unique.length + ' unique';
  return {
    tokens: tokens,
    count: count,
    unique: unique,
    frequencies: frequencies,
    summary: summary
  };
}
